-- =============================================================================
-- Migration V11: Tạo bảng khảo sát đơn hàng
-- Tables: survey_time_slots, booking_surveys, survey_attachments
-- =============================================================================

-- 1. Bảng survey_time_slots (Khung giờ khảo sát)
CREATE TABLE IF NOT EXISTS "survey_time_slots" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  CONSTRAINT uq_survey_time_slots_range UNIQUE ("start_time", "end_time"),
  CONSTRAINT chk_survey_time_slots_range CHECK (end_time > start_time)
);

-- 2. Bảng booking_surveys (Lịch khảo sát của đơn)
CREATE TABLE IF NOT EXISTS "booking_surveys" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "survey_method" varchar(30) NOT NULL,
  "survey_date" date NOT NULL,
  "survey_time_slot_id" int NOT NULL,
  "survey_staff_id" bigint NOT NULL,
  "status" varchar(30) NOT NULL DEFAULT 'PENDING',
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_booking_surveys_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surveys_time_slot FOREIGN KEY ("survey_time_slot_id") REFERENCES "survey_time_slots" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surveys_staff FOREIGN KEY ("survey_staff_id") REFERENCES "staff" ("user_id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX IF NOT EXISTS idx_booking_surveys_booking_id ON "booking_surveys" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_booking_surveys_booking_status ON "booking_surveys" ("booking_id", "status");
CREATE INDEX IF NOT EXISTS idx_booking_surveys_staff_schedule ON "booking_surveys" ("survey_staff_id", "survey_date", "survey_time_slot_id");

-- 3. Bảng survey_attachments (Ảnh/video/tài liệu khảo sát)
CREATE TABLE IF NOT EXISTS "survey_attachments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "survey_id" int NOT NULL,
  "file_url" varchar(1000) NOT NULL,
  "file_type" varchar(30) NOT NULL,
  "uploaded_by" bigint,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_survey_attachments_survey FOREIGN KEY ("survey_id") REFERENCES "booking_surveys" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_survey_attachments_uploaded_by FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX IF NOT EXISTS idx_survey_attachments_survey_id ON "survey_attachments" ("survey_id");

-- 4. Seed khung giờ khảo sát mặc định
INSERT INTO "survey_time_slots" ("start_time", "end_time", "is_active")
VALUES
  ('08:00', '10:00', true),
  ('10:00', '12:00', true),
  ('13:30', '15:30', true),
  ('15:30', '17:30', true)
